const images={desert:'https://images.unsplash.com/photo-1682687221006-b7fd60cf9dd0?auto=format&fit=crop&w=2200&q=85',city:'https://images.unsplash.com/photo-1577579566380-70290779519c?auto=format&fit=crop&w=1200&q=85',ocean:'https://images.unsplash.com/photo-1455264745730-cb3b76250ae8?auto=format&fit=crop&w=1200&q=85',portrait:'https://images.unsplash.com/photo-1513475474325-413b8da9459a?auto=format&fit=crop&w=1200&q=85'};
document.querySelector('#hero-image').src=images.desert;
const works=[
{title:'无界之境',en:'BEYOND THE HORIZON',type:'品牌影片',year:'2026',image:'desert',duration:'02′ 36″',client:'旷野 / 户外生活概念',desc:'当城市的边界消失，我们重新听见自己的声音。以一段向旷野出发的旅程，讲述人与自然之间最原始的连接。',approach:'用极远景呈现人的渺小，用触感细节放大内心的自由。暖金色沙丘与克制的留白，让品牌精神在环境中自然发生。'},
{title:'凌晨四点的城市',en:'WHILE THE CITY SLEEPS',type:'纪录片',year:'2026',image:'city',duration:'08′ 12″',client:'城市观察 / 人文纪录概念',desc:'在城市醒来之前，有些人的一天早已开始。循着街灯与车轮，我们去看见那些平凡却支撑着日常生活的身影。',approach:'低照度实景拍摄与环境声音贯穿叙事，以观察式镜头保留生活原本的节奏。'},
{title:'向海而生',en:'INTO THE BLUE',type:'品牌影片',year:'2025',image:'ocean',duration:'01′ 48″',client:'潮汐 / 运动品牌概念',desc:'浪潮从不等待。一个关于勇气、反复尝试和向前一步的故事，献给每一个愿意开始的人。',approach:'远景与近距离运动视角交替，利用浪潮形成的天然节奏组织剪辑，让声音与呼吸共同推动故事。'},
{title:'光经过的地方',en:'THE LIGHT BETWEEN US',type:'创意短片',year:'2025',image:'portrait',duration:'04′ 20″',client:'帧外原创 / 人物短片概念',desc:'一扇窗，一段等待，一束每天都会到来的光。用安静的日常片段，讲述一次与自己的和解。',approach:'坚持自然光与有限空间，用表演的细微变化代替台词，让窗外世界与人物心境相互映照。'},
{title:'风的形状',en:'WHERE THE WIND GOES',type:'创意短片',year:'2024',image:'desert',duration:'03′ 15″',client:'帧外实验 / 视觉诗概念',desc:'看不见的风，把经过的地方变成自己的形状。一首关于时间、地貌与记忆的视觉诗。',approach:'以重复的地形和缓慢变化的光影构建视觉母题，在静止与运动之间寻找一种新的观看方式。'},
{title:'海岸线上的人',en:'LIVES ALONG THE SHORE',type:'纪录片',year:'2024',image:'ocean',duration:'12′ 08″',client:'海岸故事 / 自然人文概念',desc:'一条海岸线，连接着不同的人生。听海边的人讲述季节、离开与归来，记录人与海相处的方式。',approach:'让人物的真实声音主导结构，以海面、岸线和日常劳动作为段落之间的自然连接。'}];
const projects=document.querySelector('#projects');
function render(filter='all') {
  projects.innerHTML=works.map((p,i)=>({p,i})).filter(({p})=>filter==='all'||p.type===filter).map(({p,i})=>`<div class="project-slot"><button class="project" data-project="${i}" aria-label="查看${p.title}项目详情"><div class="project-image"><img loading="lazy" draggable="false" src="${images[p.image]}" alt="${p.title}的概念影像"><span class="project-tag">${p.type} / ${p.year}</span><span class="project-index">0${i+1}</span><span class="holo-play" aria-hidden="true">↗</span><span class="project-title-image">${p.title}<small>${p.en}</small></span><span class="holo-corner" aria-hidden="true"></span></div><div class="project-info"><div><h3>${p.title}</h3><p>${p.type} · ${p.duration} · ${p.year}</p></div><span class="project-arrow" aria-hidden="true">↗</span></div></button></div>`).join('');
  projects.scrollLeft=0;
  projects.dispatchEvent(new CustomEvent('galleryrender'));
}
render();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render(b.dataset.filter)}));
let lastFocus;function openDialog(d){lastFocus=document.activeElement;d.showModal();document.body.style.overflow='hidden'}function closeDialog(d){d.close();document.body.style.overflow='';lastFocus?.focus()}
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>closeDialog(d));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}});d.addEventListener('close',()=>{document.body.style.overflow='';document.querySelector('#reel-video').pause()})});
function showProject(index){if(window.framePortfolio){window.framePortfolio.openProject(index);return;}const p=works[index];document.querySelector('#project-detail').innerHTML=`<img class="detail-image" src="${images[p.image]}" alt="${p.title}概念影像"><div class="detail-content"><span class="mini">CONCEPT PROJECT / ${p.en}</span><h2>${p.title}</h2><p>${p.desc}</p><div class="detail-meta"><span>项目方向<b>${p.client}</b></span><span>影片类型 / 年份<b>${p.type} / ${p.year}</b></span><span>概念时长<b>${p.duration}</b></span></div><h3>创作思路</h3><p>${p.approach}</p><p class="demo-note">此为概念项目档案，未提供真实成片；图片仅用于视觉方向展示。</p><a class="detail-link" href="#contact">一起创作这样的故事 ↗</a></div>`;document.querySelector('.detail-link').addEventListener('click',()=>closeDialog(document.querySelector('#project-dialog')));openDialog(document.querySelector('#project-dialog'))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(b)showProject(Number(b.dataset.project));});
document.querySelector('#showreel').addEventListener('click',()=>openDialog(document.querySelector('#reel-dialog')));
const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const isOpen=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(isOpen));menu.setAttribute('aria-label',isOpen?'关闭导航':'打开导航');menu.textContent=isOpen?'✕':'☰'});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);if(String(data.get('idea')).trim().length<10){document.querySelector('#form-status').textContent='请用至少 10 个有效字符描述你的想法。';return}const content=`FRAME 帧外影业 / 项目需求简报\n生成日期：${new Date().toLocaleDateString('zh-CN')}\n\n姓名 / 公司：${data.get('name')}\n联系邮箱：${data.get('email')}\n项目类型：${data.get('type')}\n预计预算：${data.get('budget')}\n\n项目想法：\n${data.get('idea')}\n\n注：此简报由概念网站在本地生成，尚未发送给任何公司。`;const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FRAME-项目需求简报.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='✓ 项目简报已生成并下载。你填写的信息未被上传。'});

window.FRAME_DATA={works,images};
